const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  await page.goto('http://localhost:50723/form/index.html');

  await page.fill('[name="name"], #name, input[placeholder*="Name"], input[id*="name"]', 'Test User');
  await page.fill('[name="email"], #email, input[type="email"]', 'test@example.com');
  await page.fill('[name="phone"], #phone, input[type="tel"], input[placeholder*="Phone"]', '+1-555-0100');
  await page.fill('[name="company"], #company, input[placeholder*="Company"]', 'Acme Corp');
  await page.selectOption('[name="country"], #country, select', { label: 'United States' });
  await page.fill('[name="message"], #message, textarea', 'This is a test message.');

  await page.click('button[type="submit"], input[type="submit"], button:has-text("Send")');

  await page.waitForSelector('#token', { timeout: 10000 });

  const token = await page.textContent('#token');

  const fs = require('fs');
  fs.writeFileSync(
    '/var/folders/h7/mhpz888d6xzcm62796jyks1c0000gn/T/clivsmcp-playwright-baseline-tier1_form-sz59cH/form_result.txt',
    token.trim()
  );

  console.log('Token:', token.trim());

  await browser.close();
})();

